 ):\n        work_dossier = None\n        verification = None\n    verification_result = str(verification.get(\"result\") or \"\") if verification is not None else None\n    current_results = tuple(_coerce_work_result(item) for item in work_results.get(\"work_results\", []))\n    current_verification = verify_run(current_task_card, current_plan, current_results).model_dump()\n    verification_checked_at = datetime.now(timezone.utc).isoformat().replace(\"+00:00\", \"Z\")\n    host_context = _inspect_host_context(\n        agent_root=resolved_agent_root,\n        skills_catalog=skills_catalog,\n        skills_catalog_path=skills_catalog_path,\n        host_id=host_id,\n        workspace_root=workspace_root,\n    )\n    inspected_artifact_paths = {\n        kind: (run_root / relative_path).resolve()\n        for kind, relative_path in projection.artifact_sink.artifact_paths\n    }\n    inspected_primary_document_paths = {\n        kind: (run_root / relative_path).resolve()\n        for kind, relative_path in projection.artifact_sink.primary_document_paths\n    }\n    inspected_manifest_path = (\n        run_root / projection.artifact_sink.manifest_path\n    ).resolve()\n    manifest_payload: dict[str, object] | None = None\n    if inspected_manifest_path.is_file():\n        manifest_payload = load_runtime_artifact_manifest(\n            projection,\n            path=inspected_manifest_path,\n        )\n    inputs_are_current = declared_inputs_are_current(current_task_card)\n    approved_units = {unit.id: unit for unit in current_plan.work_units}\n    completed_ids = {\n        result.work_unit_id for result in current_results\n        if inputs_are_current and result.work_unit_id in approved_units\n        and _completed_result_artifacts_are_current(result, approved_units[result.work_unit_id])\n    }\n    revision_count = len(current_task_card.accepted_revisions)\n    state_is_current = (\n        run_state.task_id == current_task_card.id\n        and run_state.accepte